def search_google_scholar_key_words(query, num_results=None, **_extra):
    import json, os, datetime, time, re, hashlib, random, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0484000" if __import__("os").path.isdir("./environment_mix/0484000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(api_key_id, endpoint, status, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _normalize_query(q):
        q = q.strip()
        q = re.sub(r"\s+", " ", q)
        return q

    def _resolve_active_key_for_call():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        # Ambient auth: pick a workable active key
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                # validate required limit fields
                if isinstance(k.get("requests_per_minute_limit"), int) and k["requests_per_minute_limit"] >= 1 and \
                   isinstance(k.get("requests_per_day_limit"), int) and k["requests_per_day_limit"] >= 1 and \
                   isinstance(k.get("requests_today"), int) and k["requests_today"] >= 0 and \
                   isinstance(k.get("day_window_start"), str):
                    return k, keys
        return None, keys

    def _minute_bucket(ts):
        return ts[:16]  # YYYY-MM-DDTHH:MM

    def _enforce_limits_and_increment(key_row, all_keys, endpoint):
        # day window reset
        dws = _parse_dt(key_row.get("day_window_start"))
        now_dt = _parse_dt(now)
        if dws is None or now_dt is None:
            return False, _err("VALIDATION_ERROR", "Corrupt key window timestamps.")
        if now_dt.date() != dws.date():
            key_row["day_window_start"] = now
            key_row["requests_today"] = 0

        # per-minute throttling via request logs (success+error count as requests at gateway; policy here: all calls count)
        rpm = key_row.get("requests_per_minute_limit")
        rpd = key_row.get("requests_per_day_limit")
        if not isinstance(rpm, int) or rpm < 1 or not isinstance(rpd, int) or rpd < 1:
            return False, _err("VALIDATION_ERROR", "Invalid API key limits.")

        # count in current minute
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        bucket = _minute_bucket(now)
        used_min = 0
        for r in logs:
            if isinstance(r, dict) and r.get("api_key_id") == key_row.get("id") and isinstance(r.get("created_at"), str):
                if _minute_bucket(r["created_at"]) == bucket:
                    used_min += 1

        if used_min >= rpm:
            _log_request(key_row.get("id"), endpoint, "rejected", error_code="RATE_LIMIT", error_message="Per-minute rate limit exceeded.")
            return False, _err("RATE_LIMIT", "Per-minute rate limit exceeded.", limit=rpm)

        # daily quota check (only successful calls must increment; but exceeding must be refused before work)
        if key_row.get("requests_today", 0) >= rpd:
            _log_request(key_row.get("id"), endpoint, "rejected", error_code="QUOTA_EXCEEDED", error_message="Daily request quota exceeded.")
            return False, _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rpd)

        # allowed; increment requests_today immediately as this call is considered successful on return; final increment happens on success
        return True, None

    def _persist_key_update(all_keys):
        _save("api_keys.json", all_keys)

    def _gen_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    def _dedupe_pub_id(pubs, cluster_id, title, year):
        if cluster_id is not None:
            for p in pubs:
                if isinstance(p, dict) and p.get("scholar_cluster_id") == cluster_id:
                    return p.get("id")
        # optional title+year
        norm_title = re.sub(r"\s+", " ", (title or "").strip()).lower()
        if norm_title:
            for p in pubs:
                if not isinstance(p, dict):
                    continue
                t = p.get("title")
                y = p.get("year")
                if isinstance(t, str) and re.sub(r"\s+", " ", t.strip()).lower() == norm_title and y == year:
                    return p.get("id")
        return None

    # Validate input
    if not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string.")
    query_n = _normalize_query(query)
    if not query_n:
        return _err("VALIDATION_ERROR", "query must not be empty.")
    if num_results is None:
        num_results = 5
    if not isinstance(num_results, int):
        return _err("VALIDATION_ERROR", "num_results must be an integer.")
    if num_results < 1 or num_results > 50:
        return _err("VALIDATION_ERROR", "num_results must be between 1 and 50.")

    # Resolve ambient key
    key, all_keys = _resolve_active_key_for_call()
    if key is None:
        _log_request(None, "search_google_scholar_key_words", "rejected", error_code="UNAUTHORIZED", error_message="No active API key available.")
        return _err("UNAUTHORIZED", "No active API key available for this call.")

    if key.get("status") != "active":
        _log_request(key.get("id"), "search_google_scholar_key_words", "rejected", error_code="UNAUTHORIZED", error_message="API key not active.")
        return _err("UNAUTHORIZED", "API key is not active.")

    ok, e = _enforce_limits_and_increment(key, all_keys, "search_google_scholar_key_words")
    if not ok:
        return e

    # Create search row queued -> running -> succeeded
    searches = _load("scholar_searches.json")
    if not isinstance(searches, list):
        searches = []
    search_id = _gen_id("srch")
    search_row = {
        "id": search_id,
        "api_key_id": key["id"],
        "search_type": "keywords",
        "query": query_n,
        "author": None,
        "year_start": None,
        "year_end": None,
        "num_results_requested": num_results,
        "status": "queued",
        "executed_at": None,
        "completed_at": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_count": 0,
        "created_at": now,
        "updated_at": now
    }
    searches.append(search_row)
    _save("scholar_searches.json", searches)

    # Transition to running
    executed_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    search_row["status"] = "running"
    search_row["executed_at"] = executed_at
    search_row["updated_at"] = executed_at
    _save("scholar_searches.json", searches)

    # "Execute" offline: generate deterministic-ish results from query
    pubs = _load("scholar_publications.json")
    if not isinstance(pubs, list):
        pubs = []
    results = _load("search_results.json")
    if not isinstance(results, list):
        results = []

    rng_seed = int(hashlib.sha256(query_n.encode("utf-8")).hexdigest()[:16], 16)
    rnd = random.Random(rng_seed)

    created_pub_ids = []
    new_results = []

    for i in range(1, num_results + 1):
        cluster = "c_" + hashlib.sha1((query_n + "|" + str(i)).encode("utf-8")).hexdigest()[:12]
        title = f"{query_n} — Result {i}"
        year = 2000 + (rng_seed + i) % 26
        authors_text = None
        if rnd.random() < 0.85:
            authors_text = "A. Author, B. Researcher"
        venue = None
        if rnd.random() < 0.6:
            venue = "Journal of Offline Scholar"
        snippet = f"Offline indexed snippet for '{query_n}' (rank {i})."
        cited_by = None
        if rnd.random() < 0.7:
            cited_by = int(rnd.random() * 500)

        pub_id = _dedupe_pub_id(pubs, cluster, title, year)
        if pub_id is None:
            pub_id = _gen_id("pub")
            pub_row = {
                "id": pub_id,
                "scholar_cluster_id": cluster,
                "title": title,
                "authors_text": authors_text,
                "publication_venue": venue,
                "year": year,
                "snippet": snippet,
                "cited_by_count": cited_by,
                "url": "https://scholar.google.com/scholar?cluster=" + cluster,
                "pdf_url": None,
                "source": "google_scholar",
                "status": "active",
                "first_seen_at": executed_at,
                "last_seen_at": executed_at,
                "created_at": executed_at,
                "updated_at": executed_at
            }
            pubs.append(pub_row)
        else:
            # update last_seen_at
            for p in pubs:
                if isinstance(p, dict) and p.get("id") == pub_id:
                    p["last_seen_at"] = executed_at
                    p["updated_at"] = executed_at
                    break

        # unique(search_id, rank) and unique(search_id, publication_id)
        sr_id = _gen_id("hit")
        hit = {
            "id": sr_id,
            "search_id": search_id,
            "publication_id": pub_id,
            "rank": i,
            "snippet_override": None,
            "raw_result": None,
            "created_at": executed_at,
            "updated_at": executed_at
        }
        created_pub_ids.append(pub_id)
        new_results.append(hit)

    # Persist pubs and results
    pubs_by_id = {p.get("id"): p for p in pubs if isinstance(p, dict) and isinstance(p.get("id"), str)}
    # Ensure referenced publication ids exist
    for hit in new_results:
        if hit["publication_id"] not in pubs_by_id:
            # fail the search
            search_row["status"] = "failed"
            search_row["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            search_row["updated_at"] = search_row["completed_at"]
            search_row["error_code"] = "INTEGRITY_ERROR"
            search_row["error_message"] = "Publication reference missing during persistence."
            search_row["result_count"] = 0
            _save("scholar_searches.json", searches)
            _log_request(key.get("id"), "search_google_scholar_key_words", "error", error_code="INTEGRITY_ERROR", error_message=search_row["error_message"])
            return _err("CONFLICT", "Failed to persist results due to integrity error.")

    # Enforce uniqueness constraints for search_results
    existing_pairs = set()
    existing_rank = set()
    for r in results:
        if isinstance(r, dict) and r.get("search_id") == search_id:
            existing_pairs.add((r.get("search_id"), r.get("publication_id")))
            existing_rank.add((r.get("search_id"), r.get("rank")))
    for hit in new_results:
        if (hit["search_id"], hit["publication_id"]) in existing_pairs or (hit["search_id"], hit["rank"]) in existing_rank:
            # Should never happen for new search_id, but enforce
            search_row["status"] = "failed"
            search_row["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            search_row["updated_at"] = search_row["completed_at"]
            search_row["error_code"] = "DUPLICATE_RESULT"
            search_row["error_message"] = "Duplicate search result constraint violation."
            search_row["result_count"] = 0
            _save("scholar_searches.json", searches)
            _log_request(key.get("id"), "search_google_scholar_key_words", "error", error_code="DUPLICATE_RESULT", error_message=search_row["error_message"])
            return _err("CONFLICT", "Duplicate search result constraint violation.")

    results.extend(new_results)
    _save("scholar_publications.json", pubs)
    _save("search_results.json", results)

    # Transition to succeeded
    completed_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    search_row["status"] = "succeeded"
    search_row["completed_at"] = completed_at
    search_row["updated_at"] = completed_at
    search_row["result_count"] = len(new_results)
    _save("scholar_searches.json", searches)

    # Increment counters for successful tool call
    key["requests_today"] = int(key.get("requests_today", 0)) + 1
    key["last_used_at"] = completed_at
    key["updated_at"] = completed_at
    _persist_key_update(all_keys)

    # Build response
    out_rows = []
    pubs_map = {p["id"]: p for p in pubs if isinstance(p, dict) and isinstance(p.get("id"), str)}
    for hit in sorted(new_results, key=lambda x: x["rank"]):
        pub = pubs_map.get(hit["publication_id"])
        if not pub:
            continue
        out_rows.append({
            "rank": hit["rank"],
            "publication": {
                "id": pub.get("id"),
                "scholar_cluster_id": pub.get("scholar_cluster_id"),
                "title": pub.get("title"),
                "authors_text": pub.get("authors_text"),
                "publication_venue": pub.get("publication_venue"),
                "year": pub.get("year"),
                "snippet": pub.get("snippet"),
                "cited_by_count": pub.get("cited_by_count"),
                "url": pub.get("url"),
                "pdf_url": pub.get("pdf_url"),
                "source": pub.get("source"),
                "status": pub.get("status"),
            }
        })

    _log_request(key.get("id"), "search_google_scholar_key_words", "ok", meta={"search_id": search_id, "result_count": len(out_rows)})
    return {
        "search": {
            "id": search_id,
            "search_type": "keywords",
            "query": query_n,
            "num_results_requested": num_results,
            "status": "succeeded",
            "executed_at": executed_at,
            "completed_at": completed_at,
            "result_count": len(out_rows)
        },
        "results": out_rows
    }

def search_google_scholar_advanced(query, author=None, year_range=None, num_results=None, **_extra):
    import json, os, datetime, time, re, hashlib, random, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0484000" if __import__("os").path.isdir("./environment_mix/0484000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(api_key_id, endpoint, status, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _normalize_text(s):
        s = s.strip()
        s = re.sub(r"\s+", " ", s)
        return s

    def _resolve_active_key_for_call():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                if isinstance(k.get("requests_per_minute_limit"), int) and k["requests_per_minute_limit"] >= 1 and \
                   isinstance(k.get("requests_per_day_limit"), int) and k["requests_per_day_limit"] >= 1 and \
                   isinstance(k.get("requests_today"), int) and k["requests_today"] >= 0 and \
                   isinstance(k.get("day_window_start"), str):
                    return k, keys
        return None, keys

    def _minute_bucket(ts):
        return ts[:16]

    def _enforce_limits(key_row, endpoint):
        dws = _parse_dt(key_row.get("day_window_start"))
        now_dt = _parse_dt(now)
        if dws is None or now_dt is None:
            return False, _err("VALIDATION_ERROR", "Corrupt key window timestamps.")
        if now_dt.date() != dws.date():
            key_row["day_window_start"] = now
            key_row["requests_today"] = 0

        rpm = key_row.get("requests_per_minute_limit")
        rpd = key_row.get("requests_per_day_limit")
        if not isinstance(rpm, int) or rpm < 1 or not isinstance(rpd, int) or rpd < 1:
            return False, _err("VALIDATION_ERROR", "Invalid API key limits.")

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        bucket = _minute_bucket(now)
        used_min = 0
        for r in logs:
            if isinstance(r, dict) and r.get("api_key_id") == key_row.get("id") and isinstance(r.get("created_at"), str):
                if _minute_bucket(r["created_at"]) == bucket:
                    used_min += 1
        if used_min >= rpm:
            _log_request(key_row.get("id"), endpoint, "rejected", error_code="RATE_LIMIT", error_message="Per-minute rate limit exceeded.")
            return False, _err("RATE_LIMIT", "Per-minute rate limit exceeded.", limit=rpm)

        if key_row.get("requests_today", 0) >= rpd:
            _log_request(key_row.get("id"), endpoint, "rejected", error_code="QUOTA_EXCEEDED", error_message="Daily request quota exceeded.")
            return False, _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rpd)

        return True, None

    def _persist_key_update(all_keys):
        _save("api_keys.json", all_keys)

    def _gen_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    def _dedupe_pub_id(pubs, cluster_id, title, year):
        if cluster_id is not None:
            for p in pubs:
                if isinstance(p, dict) and p.get("scholar_cluster_id") == cluster_id:
                    return p.get("id")
        norm_title = re.sub(r"\s+", " ", (title or "").strip()).lower()
        if norm_title:
            for p in pubs:
                if not isinstance(p, dict):
                    continue
                t = p.get("title")
                y = p.get("year")
                if isinstance(t, str) and re.sub(r"\s+", " ", t.strip()).lower() == norm_title and y == year:
                    return p.get("id")
        return None

    # Validate input
    if not isinstance(query, str):
        return _err("VALIDATION_ERROR", "query must be a string.")
    query_n = _normalize_text(query)
    if not query_n:
        return _err("VALIDATION_ERROR", "query must not be empty.")

    if num_results is None:
        num_results = 5
    if not isinstance(num_results, int):
        return _err("VALIDATION_ERROR", "num_results must be an integer.")
    if num_results < 1 or num_results > 50:
        return _err("VALIDATION_ERROR", "num_results must be between 1 and 50.")

    author_n = None
    if author is not None:
        if not isinstance(author, str):
            return _err("VALIDATION_ERROR", "author must be a string or null.")
        author_n = _normalize_text(author)
        if author_n == "":
            author_n = None

    year_start = None
    year_end = None
    if year_range is not None:
        if not isinstance(year_range, list) or len(year_range) != 2:
            return _err("VALIDATION_ERROR", "year_range must be an array of exactly 2 integers [start, end].")
        ys, ye = year_range[0], year_range[1]
        if not isinstance(ys, int) or not isinstance(ye, int):
            return _err("VALIDATION_ERROR", "year_range bounds must be integers.")
        if ys < 1600 or ye > 2200 or ys > ye:
            return _err("VALIDATION_ERROR", "year_range must satisfy 1600 <= start <= end <= 2200.")
        year_start, year_end = ys, ye

    # Resolve ambient key
    key, all_keys = _resolve_active_key_for_call()
    if key is None:
        _log_request(None, "search_google_scholar_advanced", "rejected", error_code="UNAUTHORIZED", error_message="No active API key available.")
        return _err("UNAUTHORIZED", "No active API key available for this call.")
    if key.get("status") != "active":
        _log_request(key.get("id"), "search_google_scholar_advanced", "rejected", error_code="UNAUTHORIZED", error_message="API key not active.")
        return _err("UNAUTHORIZED", "API key is not active.")

    ok, e = _enforce_limits(key, "search_google_scholar_advanced")
    if not ok:
        return e

    searches = _load("scholar_searches.json")
    if not isinstance(searches, list):
        searches = []
    search_id = _gen_id("srch")
    search_row = {
        "id": search_id,
        "api_key_id": key["id"],
        "search_type": "advanced",
        "query": query_n,
        "author": author_n,
        "year_start": year_start,
        "year_end": year_end,
        "num_results_requested": num_results,
        "status": "queued",
        "executed_at": None,
        "completed_at": None,
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "result_count": 0,
        "created_at": now,
        "updated_at": now
    }
    searches.append(search_row)
    _save("scholar_searches.json", searches)

    executed_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    search_row["status"] = "running"
    search_row["executed_at"] = executed_at
    search_row["updated_at"] = executed_at
    _save("scholar_searches.json", searches)

    pubs = _load("scholar_publications.json")
    if not isinstance(pubs, list):
        pubs = []
    results = _load("search_results.json")
    if not isinstance(results, list):
        results = []

    seed_material = query_n + "|" + (author_n or "") + "|" + (str(year_start) if year_start is not None else "") + "|" + (str(year_end) if year_end is not None else "")
    rng_seed = int(hashlib.sha256(seed_material.encode("utf-8")).hexdigest()[:16], 16)
    rnd = random.Random(rng_seed)

    new_results = []
    for i in range(1, num_results + 1):
        cluster = "c_" + hashlib.sha1((seed_material + "|" + str(i)).encode("utf-8")).hexdigest()[:12]
        title = f"{query_n} — Advanced Result {i}"
        if author_n:
            title = f"{title} ({author_n})"
        year = None
        if year_start is not None and year_end is not None:
            span = max(0, year_end - year_start)
            year = year_start + (rng_seed + i) % (span + 1 if span >= 0 else 1)
        else:
            year = 2000 + (rng_seed + i) % 26

        authors_text = author_n if author_n else ("A. Author, B. Researcher" if rnd.random() < 0.85 else None)
        venue = "Journal of Offline Scholar" if rnd.random() < 0.6 else None
        snippet = f"Offline indexed snippet for '{query_n}' (advanced rank {i})."
        cited_by = int(rnd.random() * 800) if rnd.random() < 0.7 else None

        pub_id = _dedupe_pub_id(pubs, cluster, title, year)
        if pub_id is None:
            pub_id = _gen_id("pub")
            pub_row = {
                "id": pub_id,
                "scholar_cluster_id": cluster,
                "title": title,
                "authors_text": authors_text,
                "publication_venue": venue,
                "year": year,
                "snippet": snippet,
                "cited_by_count": cited_by,
                "url": "https://scholar.google.com/scholar?cluster=" + cluster,
                "pdf_url": None,
                "source": "google_scholar",
                "status": "active",
                "first_seen_at": executed_at,
                "last_seen_at": executed_at,
                "created_at": executed_at,
                "updated_at": executed_at
            }
            pubs.append(pub_row)
        else:
            for p in pubs:
                if isinstance(p, dict) and p.get("id") == pub_id:
                    p["last_seen_at"] = executed_at
                    p["updated_at"] = executed_at
                    break

        hit = {
            "id": _gen_id("hit"),
            "search_id": search_id,
            "publication_id": pub_id,
            "rank": i,
            "snippet_override": None,
            "raw_result": None,
            "created_at": executed_at,
            "updated_at": executed_at
        }
        new_results.append(hit)

    pubs_by_id = {p.get("id"): p for p in pubs if isinstance(p, dict) and isinstance(p.get("id"), str)}
    for hit in new_results:
        if hit["publication_id"] not in pubs_by_id:
            search_row["status"] = "failed"
            search_row["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            search_row["updated_at"] = search_row["completed_at"]
            search_row["error_code"] = "INTEGRITY_ERROR"
            search_row["error_message"] = "Publication reference missing during persistence."
            search_row["result_count"] = 0
            _save("scholar_searches.json", searches)
            _log_request(key.get("id"), "search_google_scholar_advanced", "error", error_code="INTEGRITY_ERROR", error_message=search_row["error_message"])
            return _err("CONFLICT", "Failed to persist results due to integrity error.")

    existing_pairs = set()
    existing_rank = set()
    for r in results:
        if isinstance(r, dict) and r.get("search_id") == search_id:
            existing_pairs.add((r.get("search_id"), r.get("publication_id")))
            existing_rank.add((r.get("search_id"), r.get("rank")))
    for hit in new_results:
        if (hit["search_id"], hit["publication_id"]) in existing_pairs or (hit["search_id"], hit["rank"]) in existing_rank:
            search_row["status"] = "failed"
            search_row["completed_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            search_row["updated_at"] = search_row["completed_at"]
            search_row["error_code"] = "DUPLICATE_RESULT"
            search_row["error_message"] = "Duplicate search result constraint violation."
            search_row["result_count"] = 0
            _save("scholar_searches.json", searches)
            _log_request(key.get("id"), "search_google_scholar_advanced", "error", error_code="DUPLICATE_RESULT", error_message=search_row["error_message"])
            return _err("CONFLICT", "Duplicate search result constraint violation.")

    results.extend(new_results)
    _save("scholar_publications.json", pubs)
    _save("search_results.json", results)

    completed_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    search_row["status"] = "succeeded"
    search_row["completed_at"] = completed_at
    search_row["updated_at"] = completed_at
    search_row["result_count"] = len(new_results)
    _save("scholar_searches.json", searches)

    key["requests_today"] = int(key.get("requests_today", 0)) + 1
    key["last_used_at"] = completed_at
    key["updated_at"] = completed_at
    _persist_key_update(all_keys)

    out_rows = []
    pubs_map = {p["id"]: p for p in pubs if isinstance(p, dict) and isinstance(p.get("id"), str)}
    for hit in sorted(new_results, key=lambda x: x["rank"]):
        pub = pubs_map.get(hit["publication_id"])
        if not pub:
            continue
        out_rows.append({
            "rank": hit["rank"],
            "publication": {
                "id": pub.get("id"),
                "scholar_cluster_id": pub.get("scholar_cluster_id"),
                "title": pub.get("title"),
                "authors_text": pub.get("authors_text"),
                "publication_venue": pub.get("publication_venue"),
                "year": pub.get("year"),
                "snippet": pub.get("snippet"),
                "cited_by_count": pub.get("cited_by_count"),
                "url": pub.get("url"),
                "pdf_url": pub.get("pdf_url"),
                "source": pub.get("source"),
                "status": pub.get("status"),
            }
        })

    _log_request(key.get("id"), "search_google_scholar_advanced", "ok", meta={"search_id": search_id, "result_count": len(out_rows)})
    return {
        "search": {
            "id": search_id,
            "search_type": "advanced",
            "query": query_n,
            "author": author_n,
            "year_start": year_start,
            "year_end": year_end,
            "num_results_requested": num_results,
            "status": "succeeded",
            "executed_at": executed_at,
            "completed_at": completed_at,
            "result_count": len(out_rows)
        },
        "results": out_rows
    }

def get_author_info(author_name, **_extra):
    import json, os, datetime, time, re, uuid, hashlib, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0484000" if __import__("os").path.isdir("./environment_mix/0484000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _log_request(api_key_id, endpoint, status, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _resolve_active_key_for_call():
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        for k in keys:
            if isinstance(k, dict) and k.get("status") == "active":
                if isinstance(k.get("requests_per_minute_limit"), int) and k["requests_per_minute_limit"] >= 1 and \
                   isinstance(k.get("requests_per_day_limit"), int) and k["requests_per_day_limit"] >= 1 and \
                   isinstance(k.get("requests_today"), int) and k["requests_today"] >= 0 and \
                   isinstance(k.get("day_window_start"), str):
                    return k, keys
        return None, keys

    def _minute_bucket(ts):
        return ts[:16]

    def _enforce_limits(key_row):
        # day window reset
        dws = _parse_dt(key_row.get("day_window_start"))
        if dws is None:
            return False, _err("VALIDATION_ERROR", "Corrupt key window timestamps.")
        if now_dt.date() != dws.date():
            key_row["day_window_start"] = now
            key_row["requests_today"] = 0

        rpm = key_row.get("requests_per_minute_limit")
        rpd = key_row.get("requests_per_day_limit")
        if not isinstance(rpm, int) or rpm < 1 or not isinstance(rpd, int) or rpd < 1:
            return False, _err("VALIDATION_ERROR", "Invalid API key limits.")

        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        bucket = _minute_bucket(now)
        used_min = 0
        for r in logs:
            if isinstance(r, dict) and r.get("api_key_id") == key_row.get("id") and isinstance(r.get("created_at"), str):
                if _minute_bucket(r["created_at"]) == bucket:
                    used_min += 1
        if used_min >= rpm:
            _log_request(key_row.get("id"), "get_author_info", "rejected", error_code="RATE_LIMIT", error_message="Per-minute rate limit exceeded.")
            return False, _err("RATE_LIMIT", "Per-minute rate limit exceeded.", limit=rpm)

        if key_row.get("requests_today", 0) >= rpd:
            _log_request(key_row.get("id"), "get_author_info", "rejected", error_code="QUOTA_EXCEEDED", error_message="Daily request quota exceeded.")
            return False, _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=rpd)

        return True, None

    def _normalize_name(n):
        n = n.strip()
        n = re.sub(r"\s+", " ", n)
        return n

    def _norm_key(n):
        n = _normalize_name(n)
        n = re.sub(r"[^a-z0-9 ]+", "", n.lower())
        n = re.sub(r"\s+", " ", n).strip()
        return n

    def _gen_id(prefix):
        return prefix + "_" + uuid.uuid4().hex

    # Validate input
    if not isinstance(author_name, str):
        return _err("VALIDATION_ERROR", "author_name must be a string.")
    author_disp = _normalize_name(author_name)
    if not author_disp:
        return _err("VALIDATION_ERROR", "author_name must not be empty.")
    normalized = _norm_key(author_disp)
    if not normalized:
        return _err("VALIDATION_ERROR", "author_name is invalid.")

    # Resolve ambient key for quota/rate limiting
    key, all_keys = _resolve_active_key_for_call()
    if key is None:
        _log_request(None, "get_author_info", "rejected", error_code="UNAUTHORIZED", error_message="No active API key available.")
        return _err("UNAUTHORIZED", "No active API key available for this call.")
    if key.get("status") != "active":
        _log_request(key.get("id"), "get_author_info", "rejected", error_code="UNAUTHORIZED", error_message="API key not active.")
        return _err("UNAUTHORIZED", "API key is not active.")

    ok, e = _enforce_limits(key)
    if not ok:
        return e

    profiles = _load("author_profiles.json")
    if not isinstance(profiles, list):
        profiles = []

    # Cache TTL
    TTL_SECONDS = 7 * 24 * 3600

    prof = None
    for p in profiles:
        if isinstance(p, dict) and p.get("normalized_name") == normalized:
            prof = p
            break

    def _is_fresh(p):
        if p.get("status") != "fresh":
            return False
        fa = _parse_dt(p.get("fetched_at"))
        if fa is None:
            return False
        return (now_dt - fa).total_seconds() <= TTL_SECONDS

    if prof is not None and _is_fresh(prof):
        # successful call increments usage
        completed_at = now
        key["requests_today"] = int(key.get("requests_today", 0)) + 1
        key["last_used_at"] = completed_at
        key["updated_at"] = completed_at
        _save("api_keys.json", all_keys)

        _log_request(key.get("id"), "get_author_info", "ok", meta={"cache": "hit", "author_profile_id": prof.get("id")})
        return {
            "author_profile": {
                "id": prof.get("id"),
                "normalized_name": prof.get("normalized_name"),
                "display_name": prof.get("display_name"),
                "scholar_author_id": prof.get("scholar_author_id"),
                "affiliation": prof.get("affiliation"),
                "interests": prof.get("interests"),
                "cited_by_total": prof.get("cited_by_total"),
                "h_index": prof.get("h_index"),
                "i10_index": prof.get("i10_index"),
                "profile_url": prof.get("profile_url"),
                "status": prof.get("status"),
                "fetched_at": prof.get("fetched_at"),
                "error_code": prof.get("error_code"),
                "error_message": prof.get("error_message"),
                "updated_at": prof.get("updated_at"),
                "created_at": prof.get("created_at"),
            },
            "cache": {"hit": True, "ttl_seconds": TTL_SECONDS}
        }

    # "Fetch upstream" offline: deterministically synthesize a profile.
    # If name looks unresolvable, return NOT_FOUND.
    if len(normalized) < 3:
        _log_request(key.get("id"), "get_author_info", "error", error_code="NOT_FOUND", error_message="Author name too short to resolve.")
        return _err("NOT_FOUND", "No matching author profile could be resolved.")

    # Simulated upstream failure for certain patterns to exercise failed cache state
    if "unknown" in normalized or "n a" == normalized:
        # upsert row to failed
        if prof is None:
            prof = {
                "id": _gen_id("auth"),
                "normalized_name": normalized,
                "display_name": author_disp,
                "scholar_author_id": None,
                "affiliation": None,
                "interests": None,
                "cited_by_total": None,
                "h_index": None,
                "i10_index": None,
                "profile_url": None,
                "status": "failed",
                "fetched_at": now,
                "error_code": "UPSTREAM_ERROR",
                "error_message": "Upstream could not resolve author.",
                "created_at": now,
                "updated_at": now
            }
            profiles.append(prof)
        else:
            prof["display_name"] = prof.get("display_name") or author_disp
            prof["status"] = "failed"
            prof["fetched_at"] = now
            prof["error_code"] = "UPSTREAM_ERROR"
            prof["error_message"] = "Upstream could not resolve author."
            prof["updated_at"] = now
        _save("author_profiles.json", profiles)

        _log_request(key.get("id"), "get_author_info", "error", error_code="UPSTREAM_ERROR", error_message=prof["error_message"])
        return _err("CONFLICT", "Upstream error while fetching author profile.", upstream_error="UPSTREAM_ERROR")

    seed = int(hashlib.sha256(normalized.encode("utf-8")).hexdigest()[:16], 16)
    rnd = random.Random(seed)
    scholar_author_id = "A" + hashlib.md5(normalized.encode("utf-8")).hexdigest()[:11]
    interests = []
    for term in ["machine learning", "information retrieval", "bibliometrics", "data mining", "nlp", "networks"]:
        if rnd.random() < 0.35:
            interests.append(term)
    if not interests:
        interests = ["research"]

    cited_by_total = int(rnd.random() * 50000)
    h_index = int(max(1, (cited_by_total ** 0.5) / 2))
    i10_index = int(max(0, h_index * 2 - 3))
    affiliation = "Offline University" if rnd.random() < 0.7 else None
    profile_url = "https://scholar.google.com/citations?user=" + scholar_author_id

    if prof is None:
        prof = {
            "id": _gen_id("auth"),
            "normalized_name": normalized,
            "display_name": author_disp,
            "scholar_author_id": scholar_author_id,
            "affiliation": affiliation,
            "interests": interests,
            "cited_by_total": cited_by_total,
            "h_index": h_index,
            "i10_index": i10_index,
            "profile_url": profile_url,
            "status": "fresh",
            "fetched_at": now,
            "error_code": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now
        }
        profiles.append(prof)
    else:
        # lifecycle transitions allow failed/stale -> fresh
        prof["display_name"] = author_disp or prof.get("display_name")
        prof["scholar_author_id"] = prof.get("scholar_author_id") or scholar_author_id
        prof["affiliation"] = affiliation
        prof["interests"] = interests
        prof["cited_by_total"] = cited_by_total
        prof["h_index"] = h_index
        prof["i10_index"] = i10_index
        prof["profile_url"] = profile_url
        prof["status"] = "fresh"
        prof["fetched_at"] = now
        prof["error_code"] = None
        prof["error_message"] = None
        prof["updated_at"] = now

    _save("author_profiles.json", profiles)

    # successful call increments usage
    key["requests_today"] = int(key.get("requests_today", 0)) + 1
    key["last_used_at"] = now
    key["updated_at"] = now
    _save("api_keys.json", all_keys)

    _log_request(key.get("id"), "get_author_info", "ok", meta={"cache": "miss_refresh", "author_profile_id": prof.get("id")})
    return {
        "author_profile": {
            "id": prof.get("id"),
            "normalized_name": prof.get("normalized_name"),
            "display_name": prof.get("display_name"),
            "scholar_author_id": prof.get("scholar_author_id"),
            "affiliation": prof.get("affiliation"),
            "interests": prof.get("interests"),
            "cited_by_total": prof.get("cited_by_total"),
            "h_index": prof.get("h_index"),
            "i10_index": prof.get("i10_index"),
            "profile_url": prof.get("profile_url"),
            "status": prof.get("status"),
            "fetched_at": prof.get("fetched_at"),
            "error_code": prof.get("error_code"),
            "error_message": prof.get("error_message"),
            "updated_at": prof.get("updated_at"),
            "created_at": prof.get("created_at"),
        },
        "cache": {"hit": False, "ttl_seconds": TTL_SECONDS}
    }

def get_current_api_key(api_key, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0484000" if __import__("os").path.isdir("./environment_mix/0484000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(api_key_id, endpoint, status, error_code=None, error_message=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_dt(s):
        if s is None or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    # Validate input
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request(None, "get_current_api_key", "rejected", error_code="UNAUTHORIZED", error_message="Missing api_key credential.")
        return _err("UNAUTHORIZED", "Missing or invalid api_key credential.")

    cred = api_key.strip()

    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []

    # Authenticate by matching client-visible value or id.
    # Store contains only key_hash; treat key_hash as the client-visible value for this datastore.
    key_row = None
    for k in keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == cred or k.get("key_hash") == cred:
            key_row = k
            break

    if key_row is None:
        _log_request(None, "get_current_api_key", "rejected", error_code="UNAUTHORIZED", error_message="Invalid api_key credential.")
        return _err("UNAUTHORIZED", "Invalid api_key credential.")

    # Day window reset for accurate snapshot
    now_dt = _parse_dt(now)
    dws = _parse_dt(key_row.get("day_window_start"))
    if now_dt is not None and dws is not None and now_dt.date() != dws.date():
        key_row["day_window_start"] = now
        key_row["requests_today"] = 0
        key_row["updated_at"] = now
        _save("api_keys.json", keys)

    # Refuse unusable key (vendor description says FORBIDDEN; contract codes don't include it, so use UNAUTHORIZED)
    if key_row.get("status") != "active":
        _log_request(key_row.get("id"), "get_current_api_key", "rejected", error_code="UNAUTHORIZED", error_message="API key not active.")
        return _err("UNAUTHORIZED", "API key is not usable for this operation.", status=key_row.get("status"))

    _log_request(key_row.get("id"), "get_current_api_key", "ok")
    return {
        "api_key": {
            "id": key_row.get("id"),
            "label": key_row.get("label"),
            "status": key_row.get("status"),
            "requests_per_minute_limit": key_row.get("requests_per_minute_limit"),
            "requests_per_day_limit": key_row.get("requests_per_day_limit"),
            "requests_today": key_row.get("requests_today"),
            "day_window_start": key_row.get("day_window_start"),
            "last_used_at": key_row.get("last_used_at"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at")
        }
    }

def list_scholar_searches(api_key, status=None, search_type=None, query_contains=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0484000" if __import__("os").path.isdir("./environment_mix/0484000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "TYPE_ERROR"
        try:
            x = s.strip()
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(x)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return "PARSE_ERROR"

    def _normalize_key_material(k):
        if not isinstance(k, str) or not k.strip():
            return None
        return k.strip()

    def _hash_key_material(k):
        return hashlib.sha256(k.encode("utf-8")).hexdigest()

    def _find_key(keys, presented):
        # authenticate by client-visible value (plaintext) OR id.
        for r in keys:
            if not isinstance(r, dict):
                continue
            if r.get("id") == presented:
                return r
        h = _hash_key_material(presented)
        for r in keys:
            if not isinstance(r, dict):
                continue
            if r.get("key_hash") == h:
                return r
        return None

    def _minute_window_start(dt):
        return dt.replace(second=0, microsecond=0)

    def _load_logs():
        # optional collection if present in datastore
        for fname in ("request_logs.json", "usage_logs.json", "audit_logs.json", "requests.json"):
            p = os.path.join(_DB, fname)
            if os.path.exists(p):
                return fname, _load(fname)
        return None, None

    def _append_log(endpoint, api_key_id, status_code, error_code=None):
        fname, logs = _load_logs()
        if fname is None:
            return
        entry = {
            "id": f"req_{int(now.timestamp()*1000)}_{os.getpid()}_{int((time.time()%1)*1e9)}",
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso(now),
        }
        if isinstance(logs, list):
            logs.append(entry)
            _save(fname, logs)

    def _rate_limited(key_row):
        # daily window reset
        try:
            dws = key_row.get("day_window_start")
            dws_dt = _parse_dt(dws) if isinstance(dws, str) else None
            if dws_dt in ("TYPE_ERROR", "PARSE_ERROR") or dws_dt is None:
                dws_dt = now
        except Exception:
            dws_dt = now
        if (now - dws_dt) >= datetime.timedelta(days=1):
            key_row["day_window_start"] = _iso(now)
            key_row["requests_today"] = 0

        # daily quota (enforced on successful calls per business rule; we pre-check to avoid doing work)
        r_today = key_row.get("requests_today")
        if not isinstance(r_today, int) or r_today < 0:
            r_today = 0
            key_row["requests_today"] = 0
        day_lim = key_row.get("requests_per_day_limit")
        if not isinstance(day_lim, int) or day_lim < 1:
            day_lim = 1
        if r_today >= day_lim:
            return "QUOTA_EXCEEDED"

        # per-minute throttle using request logs if available; otherwise soft-enforce using last_used_at only
        rpm = key_row.get("requests_per_minute_limit")
        if not isinstance(rpm, int) or rpm < 1:
            rpm = 1

        fname, logs = _load_logs()
        if fname and isinstance(logs, list):
            ws = _minute_window_start(now)
            cnt = 0
            for e in reversed(logs):
                if not isinstance(e, dict):
                    continue
                if e.get("api_key_id") != key_row.get("id"):
                    continue
                ts = _parse_dt(e.get("created_at")) if isinstance(e.get("created_at"), str) else None
                if isinstance(ts, datetime.datetime):
                    if ts < ws:
                        break
                    cnt += 1
            if cnt >= rpm:
                return "RATE_LIMIT"
        else:
            # fallback: if last_used_at is within same minute, allow up to rpm only if we can approximate; otherwise skip
            pass

        return None

    # Validate inputs
    presented = _normalize_key_material(api_key)
    if presented is None:
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        return _err("VALIDATION_ERROR", "Invalid status", allowed=["queued", "running", "succeeded", "failed", "cancelled"])
    if search_type is not None and search_type not in ("keywords", "advanced"):
        return _err("VALIDATION_ERROR", "Invalid search_type", allowed=["keywords", "advanced"])
    if query_contains is not None and not isinstance(query_contains, str):
        return _err("VALIDATION_ERROR", "query_contains must be a string")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    ca = _parse_dt(created_after)
    if ca in ("TYPE_ERROR", "PARSE_ERROR"):
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339 date-time string")
    cb = _parse_dt(created_before)
    if cb in ("TYPE_ERROR", "PARSE_ERROR"):
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339 date-time string")

    keys = _load("api_keys.json")
    key_row = _find_key(keys, presented)
    if not key_row or key_row.get("status") != "active":
        _append_log("list_scholar_searches", key_row.get("id") if key_row else None, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is invalid or not active")

    # rate/quota
    rl = _rate_limited(key_row)
    if rl:
        _save("api_keys.json", keys)
        _append_log("list_scholar_searches", key_row.get("id"), 429 if rl == "RATE_LIMIT" else 403, rl)
        return _err(rl, "Rate limit exceeded" if rl == "RATE_LIMIT" else "Daily quota exceeded")

    searches = _load("scholar_searches.json")

    # Apply filters first (newest-first)
    def _created_dt(row):
        x = row.get("created_at")
        dt = _parse_dt(x) if isinstance(x, str) else None
        if isinstance(dt, datetime.datetime):
            return dt
        # treat missing/invalid as epoch
        return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    visible = []
    qsub = query_contains.lower() if isinstance(query_contains, str) else None
    for r in searches:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != key_row.get("id"):
            continue
        if status is not None and r.get("status") != status:
            continue
        if search_type is not None and r.get("search_type") != search_type:
            continue
        if qsub is not None:
            q = r.get("query") or ""
            if not isinstance(q, str) or qsub not in q.lower():
                continue
        cdt = _created_dt(r)
        if ca is not None and isinstance(ca, datetime.datetime) and not (cdt > ca):
            continue
        if cb is not None and isinstance(cb, datetime.datetime) and not (cdt < cb):
            continue
        visible.append(r)

    visible.sort(key=_created_dt, reverse=True)

    # Cursor handling: opaque "v1:<created_at_iso>:<id>" base64url
    def _encode_cursor(created_at_iso, rid):
        raw = f"v1:{created_at_iso}:{rid}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii")).decode("utf-8")
            parts = raw.split(":", 2)
            if len(parts) != 3 or parts[0] != "v1":
                return None
            return parts[1], parts[2]
        except Exception:
            return None

    start_idx = 0
    if cursor:
        dc = _decode_cursor(cursor)
        if dc is None:
            return _err("VALIDATION_ERROR", "Invalid cursor")
        c_iso, c_id = dc
        c_dt = _parse_dt(c_iso)
        if not isinstance(c_dt, datetime.datetime):
            return _err("VALIDATION_ERROR", "Invalid cursor")
        # find first item strictly after the cursor position in the ordered list (i.e., older than cursor)
        for i, r in enumerate(visible):
            rdt = _created_dt(r)
            if rdt < c_dt:
                start_idx = i
                break
            if rdt == c_dt and r.get("id") == c_id:
                start_idx = i + 1
                break
        else:
            start_idx = len(visible)

    page = visible[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(visible)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor(_iso(_created_dt(last)), last.get("id"))

    # successful call increments requests_today and updates last_used_at
    key_row["requests_today"] = int(key_row.get("requests_today") or 0) + 1
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
    _save("api_keys.json", keys)

    _append_log("list_scholar_searches", key_row.get("id"), 200, None)

    return {
        "object": "list",
        "data": page,
        "total": len(visible),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

