    for r in searches:
        if isinstance(r, dict) and r.get("id") == search_id and r.get("api_key_id") == key_row.get("id"):
            search_row = r
            break
    if not search_row:
        _append_log("list_search_results", key_row.get("id"), 404, "NOT_FOUND")
        return _err("NOT_FOUND", "Search not found")

    results = _load("search_results.json")
    pubs = _load("scholar_publications.json")
    pub_by_id = {p.get("id"): p for p in pubs if isinstance(p, dict) and p.get("id")}

    hits = [r for r in results if isinstance(r, dict) and r.get("search_id") == search_id]
    hits.sort(key=lambda r: r.get("rank") if isinstance(r.get("rank"), int) else 10**18)

    # Cursor: opaque "v1:<rank_int>"
    def _encode_cursor(rank):
        raw = f"v1:{rank}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(cur):
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii")).decode("utf-8")
            parts = raw.split(":", 1)
            if len(parts) != 2 or parts[0] != "v1":
                return None
            return int(parts[1])
        except Exception:
            return None

    start_idx = 0
    if cursor:
        last_rank = _decode_cursor(cursor)
        if last_rank is None:
            return _err("VALIDATION_ERROR", "Invalid cursor")
        for i, r in enumerate(hits):
            rk = r.get("rank")
            if isinstance(rk, int) and rk > last_rank:
                start_idx = i
                break
        else:
            start_idx = len(hits)

    page = hits[start_idx:start_idx + limit]
    has_more = (start_idx + limit) < len(hits)
    next_cursor = _encode_cursor(page[-1].get("rank")) if has_more and page and isinstance(page[-1].get("rank"), int) else None

    enriched = []
    for r in page:
        out = dict(r)
        if not include_raw_result and "raw_result" in out:
            out.pop("raw_result", None)
        pub = pub_by_id.get(r.get("publication_id"))
        out["publication"] = pub if pub is not None else None
        enriched.append(out)

    key_row["requests_today"] = int(key_row.get("requests_today") or 0) + 1
    key_row["last_used_at"] = _iso(now)
    key_row["updated_at"] = _iso(now)
