    _append_log("list_search_results", key_row.get("id"), 200, None)
    return {
        "object": "list",
        "search": search_row,
        "data": enriched,
        "total": len(hits),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

