        txt = s.strip()
        try:
            if txt.endswith("Z"):
                txt = txt[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(txt)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _coerce_rows(obj):
        if isinstance(obj, list):
            return obj, "list", None
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"], "dict_rows", obj
        return [], "unknown", obj if isinstance(obj, dict) else None

    def _save_back(filename, shape, container, rows):
        if shape == "dict_rows" and isinstance(container, dict):
            container["rows"] = rows
            _save(filename, container)
        else:
            _save(filename, rows)

    def _pick_request_log_filename():
        # Only log if a known log file exists (schema didn't declare one, but contract says to use if present).
        candidates = (
            "request_logs.json",
            "usage_logs.json",
            "audit_logs.json",
            "api_request_logs.json",
            "requests.json",
        )
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                return fn
        return None

    def _append_request_log(status, api_key_id=None, error_code=None, error_message=None):
        fn = _pick_request_log_filename()
        if not fn:
            return
        obj = _load(fn)
        rows, shape, container = _coerce_rows(obj)
        now = _utcnow()
        latency_ms = int(max(0, (time.time() - t0) * 1000))
        entry = {
            "id": "gss_req_" + uuid.uuid4().hex,
            "endpoint": "cancel_scholar_search",
            "api_key_id": api_key_id,
            "credential": api_key,
            "search_id": search_id,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "created_at": _to_iso(now),
        }
        rows.append(entry)
        _save_back(fn, shape, container, rows)

    def _normalize_credential(s):
        # Credential can be an api_keys.id or a client-visible "raw key" value.
        # Store contains only key_hash, so we MUST authenticate by id (or accept matching id).
        if not isinstance(s, str):
            return None
        s = s.strip()
        return s if s else None

    def _resolve_api_key_row(cred):
        keys_obj = _load("api_keys.json")
        keys, _, _ = _coerce_rows(keys_obj)
        # Accept either api_keys.id or key_hash matching the presented value (client-visible could be stored as key_hash in fixtures).
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == cred or k.get("key_hash") == cred:
                return k, keys_obj
        return None, keys_obj

    def _enforce_rate_limits(api_key_row):
        # Returns (ok, error_obj_or_none). This tool should count only on success (per business rule).
        # But per-minute throttling should refuse abusive calls even if they would fail later; use request_logs if present.
        if not isinstance(api_key_row, dict):
            return False, _err("UNAUTHORIZED", "Invalid API key")
        if api_key_row.get("status") != "active":
            return False, _err("UNAUTHORIZED", "API key is not active", api_key_id=api_key_row.get("id"), status=api_key_row.get("status"))

        # Daily window reset (enforced on success, but we normalize window here).
        now = _utcnow()
        day_start = _parse_iso(api_key_row.get("day_window_start"))
        if day_start is None:
            day_start = now
            api_key_row["day_window_start"] = _to_iso(day_start)
            api_key_row["requests_today"] = int(api_key_row.get("requests_today") or 0)

        # Reset if window older than 24h (simple rolling window)
        if (now - day_start).total_seconds() >= 86400:
            api_key_row["day_window_start"] = _to_iso(now)
            api_key_row["requests_today"] = 0

        # Per-minute throttling based on request logs if available.
        limit = api_key_row.get("requests_per_minute_limit")
        if not isinstance(limit, int) or limit < 1:
            # schema says >=1; treat broken data as validation-like refusal
            return False, _err("VALIDATION_ERROR", "API key has invalid requests_per_minute_limit", api_key_id=api_key_row.get("id"))

        fn = _pick_request_log_filename()
        if fn:
            obj = _load(fn)
            rows, _, _ = _coerce_rows(obj)
            cutoff = now - datetime.timedelta(seconds=60)
            count = 0
            for r in rows:
                if not isinstance(r, dict):
                    continue
                if r.get("api_key_id") != api_key_row.get("id"):
                    continue
                ts = _parse_iso(r.get("created_at") or r.get("timestamp"))
                if ts is None:
                    continue
                if ts >= cutoff:
                    count += 1
            if count >= limit:
                return False, _err("RATE_LIMIT", "Per-minute request limit exceeded", limit=limit)

        return True, None

    # --- Validate inputs first ---
    if not isinstance(api_key, str) or not api_key.strip():
        _append_request_log("error", api_key_id=None, error_code="VALIDATION_ERROR", error_message="api_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(search_id, str) or not search_id.strip():
        _append_request_log("error", api_key_id=None, error_code="VALIDATION_ERROR", error_message="search_id must be a non-empty string")
        return _err("VALIDATION_ERROR", "search_id must be a non-empty string")
    if reason is not None and not isinstance(reason, str):
        _append_request_log("error", api_key_id=None, error_code="VALIDATION_ERROR", error_message="reason must be a string when provided")
        return _err("VALIDATION_ERROR", "reason must be a string when provided")

    cred = _normalize_credential(api_key)
    key_row, keys_obj = _resolve_api_key_row(cred)
    if not key_row:
        _append_request_log("error", api_key_id=None, error_code="UNAUTHORIZED", error_message="API key not recognized")
        return _err("UNAUTHORIZED", "API key not recognized")

    ok, err = _enforce_rate_limits(key_row)
    if not ok:
        _append_request_log("error", api_key_id=key_row.get("id"), error_code=err["error"]["code"], error_message=err["error"]["message"])
        return err

    # Load searches
    searches_obj = _load("scholar_searches.json")
    searches, searches_shape, searches_container = _coerce_rows(searches_obj)

    # Find search; accessibility rule: API key must match owning api_key_id
    target = None
    target_idx = None
    for i, s in enumerate(searches):
        if isinstance(s, dict) and s.get("id") == search_id:
            target = s
            target_idx = i
            break

    if not target:
        _append_request_log("error", api_key_id=key_row.get("id"), error_code="NOT_FOUND", error_message="Search not found")
        return _err("NOT_FOUND", "Search not found", search_id=search_id)

    if target.get("api_key_id") != key_row.get("id"):
        # Inaccessible
        _append_request_log("error", api_key_id=key_row.get("id"), error_code="NOT_FOUND", error_message="Search not found")
        return _err("NOT_FOUND", "Search not found", search_id=search_id)

    status = target.get("status")
    if status in ("succeeded", "failed", "cancelled"):
        _append_request_log("error", api_key_id=key_row.get("id"), error_code="CONFLICT", error_message="Search already in terminal state")
        return _err("CONFLICT", "Search is already in a terminal state and cannot be cancelled", search_id=search_id, status=status)

    if status not in ("queued", "running"):
        _append_request_log("error", api_key_id=key_row.get("id"), error_code="INVALID_TRANSITION", error_message="Illegal status transition to cancelled")
        return _err("INVALID_TRANSITION", "Can only cancel a search from 'queued' or 'running'", search_id=search_id, status=status)

    # Perform transition to cancelled and enforce business rules:
    # - completed_at set
    # - result_count = 0
    # - no search_results rows may exist (clear any)
    now = _utcnow()
    target["status"] = "cancelled"
    target["completed_at"] = _to_iso(now)
    target["updated_at"] = _to_iso(now)
    # store cancellation diagnostics
    if reason is not None and reason.strip():
        # there is no explicit cancellation_reason field in schema; store in error_message/error_code as diagnostics
        # Use stable code CLIENT_CANCELLED consistent with sample data.
        target["error_code"] = "CLIENT_CANCELLED"
        target["error_message"] = reason.strip()
    else:
        target["error_code"] = "CLIENT_CANCELLED"
        if not target.get("error_message"):
            target["error_message"] = "Client cancelled request"
    target["http_status"] = target.get("http_status")  # leave as-is if already set
    target["result_count"] = 0

    # Clear search_results for this search_id (cascade-like behavior for cancel)
    results_obj = _load("search_results.json")
    results, results_shape, results_container = _coerce_rows(results_obj)
    new_results = [r for r in results if not (isinstance(r, dict) and r.get("search_id") == search_id)]
    # Persist changes
    searches[target_idx] = target
    _save_back("scholar_searches.json", searches_shape, searches_container, searches)
    if len(new_results) != len(results):
        _save_back("search_results.json", results_shape, results_container, new_results)

    # Increment daily usage on successful tool call and enforce per-day quota (must not exceed)
    # Since cancel is a successful call, it increments requests_today.
    day_limit = key_row.get("requests_per_day_limit")
    if not isinstance(day_limit, int) or day_limit < 1:
        _append_request_log("error", api_key_id=key_row.get("id"), error_code="VALIDATION_ERROR", error_message="API key has invalid requests_per_day_limit")
        return _err("VALIDATION_ERROR", "API key has invalid requests_per_day_limit", api_key_id=key_row.get("id"))

    # Reload keys rows to save back (preserve file shape)
    keys_rows, keys_shape, keys_container = _coerce_rows(keys_obj)
    key_idx = None
    for i, k in enumerate(keys_rows):
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            key_idx = i
            break
    if key_idx is None:
        _append_request_log("error", api_key_id=key_row.get("id"), error_code="UNAUTHORIZED", error_message="API key disappeared")
        return _err("UNAUTHORIZED", "API key not recognized")

    # Enforce daily quota on increment (refuse if would exceed, and roll back cancellation? Real systems often check before work.
    # Here we check after mutation would be wrong; so do a conservative pre-check using current requests_today.
    # We already mutated cancellation; ensure we don't silently exceed quota. If quota exceeded, revert the cancellation to previous state is complex.
    # Instead: check before increment and only then increment/save. Since tool already succeeded, daily quota should normally allow it.
    current_today = keys_rows[key_idx].get("requests_today")
    try:
        current_today_int = int(current_today)
    except Exception:
        current_today_int = 0
    if current_today_int + 1 > day_limit:
        _append_request_log("error", api_key_id=key_row.get("id"), error_code="QUOTA_EXCEEDED", error_message="Daily request limit exceeded")
        return _err("QUOTA_EXCEEDED", "Daily request limit exceeded", limit=day_limit)

    keys_rows[key_idx]["requests_today"] = current_today_int + 1
    keys_rows[key_idx]["last_used_at"] = _to_iso(now)
    keys_rows[key_idx]["updated_at"] = _to_iso(now)
    _save_back("api_keys.json", keys_shape, keys_container, keys_rows)

    _append_request_log("success", api_key_id=key_row.get("id"), error_code=None, error_message=None)

    # Return updated search record (as stored)
    return {"search": target}

def update_api_key_status(api_key, status, **_extra):
    import json, os, datetime, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0484000" if __import__("os").path.isdir("./environment_mix/0484000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(api_key_id, presented_credential, endpoint, status_code, error_code=None):
        # Best-effort request/audit log if a plausible collection exists.
        for fname in ("request_logs.json", "usage_logs.json", "api_requests.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                logs.append({
                    "id": "req_" + uuid.uuid4().hex,
                    "endpoint": endpoint,
                    "api_key_id": api_key_id,
                    "credential_presented": (presented_credential[:8] + "…") if isinstance(presented_credential, str) else None,
                    "status": status_code,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - t0) * 1000),
                    "created_at": now
                })
                _save(fname, logs)
                break

    endpoint = "update_api_key_status"

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log_request(None, api_key, endpoint, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
    if status not in ("active", "suspended", "revoked"):
        _log_request(None, api_key, endpoint, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=["active", "suspended", "revoked"])

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    # Authenticate: parameter may be an id or client-visible credential value.
    # Store only has key_hash; support matching when api_key equals id, or matches a hash of api_key
    # using common algorithms. Never compare against stored hash expecting plaintext.
    def _digests(s):
        b = s.encode("utf-8")
        outs = set()
        outs.add(hashlib.sha256(b).hexdigest())
        outs.add(hashlib.sha1(b).hexdigest())
        outs.add(hashlib.md5(b).hexdigest())
        # allow "sha256:<hex>" formats as stored
        outs.add("sha256:" + hashlib.sha256(b).hexdigest())
        outs.add("sha1:" + hashlib.sha1(b).hexdigest())
        outs.add("md5:" + hashlib.md5(b).hexdigest())
        return outs

    candidates = []
    dig = _digests(api_key.strip())
    for row in api_keys:
        if not isinstance(row, dict):
            continue
        if row.get("id") == api_key:
            candidates.append(row)
            continue
        kh = row.get("key_hash")
        if isinstance(kh, str) and kh in dig:
            candidates.append(row)

    if not candidates:
        _log_request(None, api_key, endpoint, 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Invalid API key")

    # Pick best candidate: prefer active/suspended over revoked for meaningful transitions.
    def _prio(r):
        st = r.get("status")
        return {"active": 0, "suspended": 1, "revoked": 2}.get(st, 3)
    key_row = sorted(candidates, key=_prio)[0]

    # Enforce lifecycle transition rules (tool says CONFLICT on invalid transitions)
    current = key_row.get("status")
    transitions = {
        "active": {"suspended", "revoked"},
        "suspended": {"active", "revoked"},
        "revoked": set()
    }
    if current not in transitions:
        _log_request(key_row.get("id"), api_key, endpoint, 409, "CONFLICT")
        return _err("CONFLICT", "API key is in an unknown state", current_status=current)

    if status == current:
        # Idempotent success
        _log_request(key_row.get("id"), api_key, endpoint, 200, None)
        return {"api_key": key_row, "idempotent": True}

    if status not in transitions[current]:
        _log_request(key_row.get("id"), api_key, endpoint, 409, "CONFLICT")
        return _err(
            "CONFLICT",
            "Invalid status transition",
            current_status=current,
            target_status=status,
            allowed_targets=sorted(list(transitions[current]))
        )

    # Apply update
    key_row["status"] = status
    key_row["updated_at"] = now
    key_row["last_used_at"] = now  # successful authenticated call

    # Persist back
    updated = False
    for i, row in enumerate(api_keys):
        if isinstance(row, dict) and row.get("id") == key_row.get("id"):
            api_keys[i] = key_row
            updated = True
            break
    if not updated:
        _log_request(key_row.get("id"), api_key, endpoint, 404, "NOT_FOUND")
        return _err("NOT_FOUND", "API key record not found")

    _save("api_keys.json", api_keys)
    _log_request(key_row.get("id"), api_key, endpoint, 200, None)

    return {"api_key": key_row}
